// Writes js/crisis-phrases.js (the browser copy) from netlify/lib/crisis-phrases.js.
// Run after changing the phrase list:  node scripts/build-crisis-phrases.mjs
// `--check` exits 1 if the committed browser copy has drifted (used by the tests).
import { readFileSync, writeFileSync } from "node:fs";
import { CRISIS_PHRASES, normaliseCrisisText } from "../netlify/lib/crisis-phrases.js";

export function renderBrowserCopy() {
  return `// GENERATED by scripts/build-crisis-phrases.mjs from netlify/lib/crisis-phrases.js.
// Do not edit by hand: change the source, then run the script. A test fails if this drifts.
// One crisis phrase list for the browser (Arron app and companion), same as the server.
(function (root) {
 'use strict';
 var PHRASES = ${JSON.stringify(CRISIS_PHRASES, null, 1).replace(/\n/g, "\n ")};
 var normalise = ${normaliseCrisisText.toString()};
 var regex = new RegExp(PHRASES.join('|'), 'i');
 root.PSCrisis = Object.freeze({
 phrases: Object.freeze(PHRASES.slice()),
 normalise: normalise,
 regex: regex,
 test: function (text) { return regex.test(normalise(text)); }
 });
})(typeof window !== 'undefined' ? window : globalThis);
`;
}

const target = new URL("../js/crisis-phrases.js", import.meta.url);
if (import.meta.url === `file://${process.argv[1]}`) {
  const next = renderBrowserCopy();
  if (process.argv.includes("--check")) {
    const now = readFileSync(target, "utf8");
    if (now !== next) {
      console.error("js/crisis-phrases.js has drifted. Run: node scripts/build-crisis-phrases.mjs");
      process.exit(1);
    }
    console.log("js/crisis-phrases.js matches netlify/lib/crisis-phrases.js");
  } else {
    writeFileSync(target, next);
    console.log("Wrote js/crisis-phrases.js");
  }
}
